package com.axl.custodian.core.sqlite;
import com.axl.custodian.api.ProcessEpoch; import java.nio.file.Path; import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.*; import org.junit.jupiter.api.io.TempDir; import static org.junit.jupiter.api.Assertions.*;
class BridgeLifecycleStoreTest { @TempDir Path dir; @Test void startHeartbeatAndInvalidatePersist(){Instant now=Instant.EPOCH; var epoch=new ProcessEpoch(UUID.randomUUID(),"bridge",now,now); try(var store=new SqliteCustodianStore(dir.resolve("bridge.db"))){store.startBridge("infinitygear",epoch);assertTrue(store.bridge(epoch.id()).orElseThrow().active());Instant later=now.plusSeconds(3);store.heartbeatBridge(epoch.id(),later);assertEquals(later,store.bridge(epoch.id()).orElseThrow().heartbeatAt());store.invalidateBridge(epoch.id());assertFalse(store.bridge(epoch.id()).orElseThrow().active());assertThrows(IllegalArgumentException.class,()->store.heartbeatBridge(epoch.id(),later));}} }
